{
  "title": "Job Application",
  "description": "Apply for an open role at our company",
  "is_public": true,
  "is_active": true,
  "allow_response_edit": true,
  "allow_multiple_submissions": true,
  "submit_message": "Thanks for applying! We'll be in touch.",
  "fields": [
    {
      "label": "Full Name",
      "field_key": "full_name",
      "field_type": "text",
      "is_required": true,
      "placeholder": "Jane Doe",
      "config": {
        "min_length": 2,
        "max_length": 100
      }
    },
    {
      "label": "Email",
      "field_key": "email",
      "field_type": "email",
      "is_required": true
    },
    {
      "label": "Years of experience",
      "field_key": "experience",
      "field_type": "number",
      "config": {
        "min": 0,
        "max": 50,
        "integer_only": true
      }
    },
    {
      "label": "Currently employed?",
      "field_key": "employed",
      "field_type": "radio",
      "is_required": true,
      "options": [
        {
          "label": "Yes",
          "value": "yes"
        },
        {
          "label": "No",
          "value": "no"
        }
      ]
    },
    {
      "label": "Current company",
      "field_key": "company",
      "field_type": "text",
      "is_required": true,
      "help_text": "Shown only when 'Currently employed?' = Yes",
      "visibility_rules": {
        "logic": "all",
        "conditions": [
          {
            "field_key": "employed",
            "operator": "equals",
            "value": "yes"
          }
        ]
      }
    },
    {
      "label": "Department",
      "field_key": "department",
      "field_type": "dropdown",
      "is_required": true,
      "options": [
        {
          "label": "Engineering",
          "value": "engineering"
        },
        {
          "label": "Sales",
          "value": "sales"
        },
        {
          "label": "Marketing",
          "value": "marketing"
        }
      ]
    },
    {
      "label": "Skills",
      "field_key": "skills",
      "field_type": "checkbox",
      "config": {
        "min_selected": 1,
        "max_selected": 3
      },
      "options": [
        {
          "label": "Python"
        },
        {
          "label": "SQL"
        },
        {
          "label": "React"
        },
        {
          "label": "Docker"
        }
      ]
    },
    {
      "label": "Available from",
      "field_key": "start_date",
      "field_type": "date",
      "config": {
        "min_date": "2026-01-01"
      }
    },
    {
      "label": "Resume",
      "field_key": "resume",
      "field_type": "file",
      "config": {
        "allowed_extensions": [
          "pdf",
          "doc",
          "docx"
        ],
        "max_size_mb": 5
      }
    },
    {
      "label": "Rate our hiring process",
      "field_key": "rating",
      "field_type": "rating",
      "config": {
        "max_rating": 5
      }
    },
    {
      "label": "I agree to the privacy policy",
      "field_key": "agree",
      "field_type": "checkbox",
      "is_required": true
    }
  ]
}
